// Extract video ID from folder path
// Supports both webhook trigger (videoPath) and watch-folder trigger (filePath)
const path = $input.first().json.videoPath || $input.first().json.filePath;
const fs = require('fs');

// Extract video ID like WC-01, GZ-01
const match = path.match(/outputs\\/([^/]+)\\/final\.mp4/);
const videoId = match ? match[1] : 'UNKNOWN';

// Get folder path
const folder = path.replace(/\\\\/g, '/').replace(/\\/[^/]+$/, '');

// Check if metadata was passed directly via webhook
const webhookTitle = $input.first().json.title;
const webhookDesc = $input.first().json.description;
const webhookTags = $input.first().json.tags;

let title = webhookTitle || `Video ${videoId}`;
let description = webhookDesc || '';
let tags = webhookTags || [];

// If not from webhook, load from script JSON
if (!webhookTitle) {
  try {
    const scriptPath = `C:/Users/PC/.paperclip/instances/default/workspaces/TKP_ACI/scripts/pending/${videoId}.json`;
    if (fs.existsSync(scriptPath)) {
      const script = JSON.parse(fs.readFileSync(scriptPath, 'utf8'));
      title = script.title || title;
      description = script.script || '';
      tags = script.tags || [];

      // Add hashtags to description
      if (tags.length > 0) {
        description += '\n\n' + tags.map(t => '#' + t).join(' ');
      }
    }
  } catch (e) {
    console.log('Could not load script:', e.message);
  }
}

const result = {
  videoId: videoId,
  folder: folder,
  videoPath: path,
  title: title,
  description: description,
  tags: tags,
  platform: 'youtube',
  status: 'pending'
};

return [{json: result}];

// Log the upload result
const fs = require('fs');
const logPath = 'C:/Users/PC/.paperclip/instances/default/workspaces/TKP_ACI/logs/youtube_upload_log.json';

const input = $input.first().json;
const logEntry = {
  timestamp: new Date().toISOString(),
  videoId: input.videoId,
  title: input.title,
  status: 'uploaded',
  videoUrl: input.videoUrl || input.id,
  platform: 'youtube'
};

try {
  let logs = [];
  if (fs.existsSync(logPath)) {
    logs = JSON.parse(fs.readFileSync(logPath, 'utf8'));
  }
  logs.push(logEntry);
  fs.writeFileSync(logPath, JSON.stringify(logs, null, 2));
} catch (e) {}

// Update script JSON with YouTube URL
try {
  const scriptPath = `C:/Users/PC/.paperclip/instances/default/workspaces/TKP_ACI/scripts/pending/${input.videoId}.json`;
  if (fs.existsSync(scriptPath)) {
    const script = JSON.parse(fs.readFileSync(scriptPath, 'utf8'));
    script.youtube_url = input.videoUrl || `https://youtube.com/shorts/${input.id}`;
    script.youtube_uploaded_at = new Date().toISOString();
    script.status = 'published';
    fs.writeFileSync(scriptPath, JSON.stringify(script, null, 2));
  }
} catch (e) {
  console.log('Could not update script:', e.message);
}

return [{json: logEntry}];
